<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {captureToolWindow,captureToolCapabilities} from './capture-tools-state.js';
 import {magnifierMenus} from './capture-tools-menus.js';
 import {createCaptureToolNativeView,magnifierKeyboard} from './capture-tools-native-view.js';
 import './capture-tools.css';
 let {state: magnifierState,profile,windowId,window:actualWindow=null,execute,registerView,available=true,active=true,controls={},getShared=null}=$props();
 let root=$state(null),message=$state(''),busy=$state(false);let originalState,originalProfile,originalId,facade,retired=false,pendingPoint=null,pointerTimer=null;
 const id=$derived(windowId??actualWindow?.id),session=$derived(captureToolWindow(magnifierState,id)),cap=$derived(captureToolCapabilities(profile,'magnifier')),shared=$derived((getShared??controls.getShared)?.('accessibility')??null),groups=$derived(magnifierMenus({state: magnifierState,profile,windowId:id})),menu=$derived(groups.find(g=>g.id===session?.menu));
 function current(){return !retired&&root?.isConnected&&magnifierState===originalState&&profile===originalProfile&&id===originalId;}
 async function command(suffix,payload={}){if(!current()||!available||!active)return;const original=root,r=await execute(`magnifier.${suffix}`,{windowId:id},payload);if(current()&&root===original)message=r?.status==='applied'?'':r?.error?.message??'The original shared Zoom is unavailable.';return r;}
 async function refresh(){if(busy||!current())return;busy=true;try{await command('refresh');}finally{if(current())busy=false;}}
 async function zoom(payload){const r=await command('zoom',payload);if(current()&&r?.status==='applied'&&(getShared??controls.getShared)?.('accessibility')?.zoom===true)refresh();}
 function pointer(event){if(!current()||!available||!active||!shared?.zoom||!session?.followPointer||session.menu||session.sheet||!facade.containsPoint({x:event.clientX,y:event.clientY}))return;pendingPoint={x:event.clientX,y:event.clientY};if(pointerTimer===null&&!busy)pointerTimer=setTimeout(samplePointer,160);}
 async function samplePointer(){pointerTimer=null;if(!pendingPoint||busy||!current())return;const point=pendingPoint;pendingPoint=null;busy=true;try{await command('sample',point);}finally{if(current()){busy=false;if(pendingPoint)pointerTimer=setTimeout(samplePointer,160);}}}
 async function mode(mode){const r=await command('settings',{mode});if(current()&&r?.status==='applied'&&shared?.zoom)refresh();}
 async function menuAction(item){if(!item.enabled)return;const r=await command(item.request.command.slice(10),item.request.payload);if(current()&&r?.status==='applied'&&session.menu)command('sheet',{menu:null});}
 function keyboard(event){if(!current()||!available||!active||!session)return;if(event.key==='Escape'&&!event.metaKey&&(session.sheet||session.menu)){event.preventDefault();command('sheet',{sheet:null,menu:null});return;}if(event.target.matches('input,select,textarea'))return;const request=magnifierKeyboard(event,profile,shared,session);if(request){event.preventDefault();if(request.suffix==='zoom')zoom(request.payload);else if(request.suffix==='settings')mode(request.payload.mode);else command(request.suffix,request.payload);}}
 onMount(()=>{originalState=magnifierState;originalProfile=profile;originalId=id;facade=createCaptureToolNativeView({getRoot:()=>root,getState:()=>magnifierState,getProfile:()=>profile,windowId:id,available:()=>current()&&available&&active,tick,getShared:getShared??controls.getShared});registerView?.(id,facade);const doc=root.ownerDocument;doc.addEventListener('pointermove',pointer);doc.addEventListener('keydown',keyboard);return()=>{retired=true;clearTimeout(pointerTimer);pendingPoint=null;doc.removeEventListener('pointermove',pointer);doc.removeEventListener('keydown',keyboard);facade.destroy();registerView?.(originalId,null,facade);};});
</script>
<section bind:this={root} class="capture-tool magnifier-tool" class:classic={cap.classic} class:windows={cap.windows} class:golden={cap.golden} class:inactive={!active} data-capture-window={id} data-profile={profile.id} role="region" aria-label={cap.label} tabindex="0">
 {#if session}
 <header class="capture-title">{#if !cap.windows}<WindowControls {active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} fullScreen={controls.fullScreen}/>{/if}<strong>{cap.label}</strong>{#if cap.windows}<button data-capture-control="close" aria-label="Close Magnifier" onclick={()=>command('window.close')}>×</button>{/if}</header>
 <div class="capture-body" inert={!available||!active||!!session.sheet}>
 <nav class="capture-menus" aria-label="Zoom menus">{#each groups.filter(g=>g.id!=='app') as group}<button data-capture-control={`menu:${group.id}`} aria-expanded={menu?.id===group.id} onclick={()=>command('sheet',{menu:menu?.id===group.id?null:group.id})}>{group.label}</button>{/each}</nav>
 {#if menu}<div class="capture-menu" role="menu">{#each menu.children as item}<button data-capture-control={item.id} role="menuitem" disabled={!item.enabled} onclick={()=>menuAction(item)}>{item.checked?'✓ ':''}{item.label}</button>{/each}</div>{/if}
 <div class="magnifier-toolbar"><button class="zoom-button" data-capture-control="zoomOut" disabled={!shared||shared.zoomScale<=1} aria-label="Zoom out" onclick={()=>zoom({scale:Math.max(1,shared.zoomScale-0.5)})}>−</button><output aria-label="Shared zoom scale">{shared?Math.round(shared.zoomScale*100)+'%':'—'}</output><button class="zoom-button" data-capture-control="zoomIn" disabled={!shared||shared.zoomScale>=5} aria-label="Zoom in" onclick={()=>zoom({enabled:true,scale:Math.min(5,shared.zoomScale+0.5)})}>+</button><button data-capture-control="power" aria-pressed={shared?.zoom??false} disabled={!shared} onclick={()=>zoom({enabled:!shared.zoom})}>{shared?.zoom?'Turn off':'Turn on'}</button><select data-capture-control="view" aria-label="Zoom view" value={session.mode} onchange={e=>mode(e.currentTarget.value)}>{#each Object.entries(cap.styles) as [value,label]}<option {value}>{label}</option>{/each}</select><button data-capture-control="settings" aria-label="Zoom settings" onclick={()=>command('sheet',{sheet:'preferences'})}>⚙</button></div>
 <div class="magnifier-display" class:lens={session.mode==='lens'} class:docked={session.mode==='docked'} class:off={!shared?.zoom}><canvas data-capture-preview width="280" height="180" aria-label="Actual magnified simulated desktop pixels"></canvas>{#if !session.sample||!shared?.zoom}<div class="magnifier-empty"><span aria-hidden="true">⌕</span><p>{!shared?'Original Accessibility source unavailable.':!shared.zoom?'Shared Accessibility Zoom is off.':'Move the pointer in the simulated desktop.'}</p></div>{/if}</div>
 <footer class="capture-actions"><label><input type="checkbox" data-capture-control="followPointer" checked={session.followPointer} onchange={e=>command('settings',{followPointer:e.currentTarget.checked})}/>Follow pointer</label><span>{Math.round(session.point.x)}, {Math.round(session.point.y)}</span><button data-capture-control="refresh" disabled={busy||!shared?.zoom} onclick={refresh}>Refresh Pixels</button></footer>
 <p class="capture-status" role="status">{message||session.status}</p><p class="capture-qualification">{cap.qualification}</p>
 </div>
 {#if session.sheet}<div class="capture-sheet" role="dialog" aria-modal="true" aria-label={session.sheet==='help'?cap.label+' Help':'Zoom Settings'}><h2>{session.sheet==='help'?cap.label+' Help':'Zoom Settings'}</h2>{#if session.sheet==='preferences'}<label><input data-capture-control="shared:zoom" type="checkbox" checked={shared?.zoom??false} disabled={!shared} onchange={e=>zoom({enabled:e.currentTarget.checked})}/>Shared Accessibility Zoom</label><label>Magnification <input data-capture-control="shared:zoomScale" type="range" min="1" max="5" step="0.5" value={shared?.zoomScale??1} disabled={!shared} onchange={e=>zoom({scale:Number(e.currentTarget.value)})}/></label><p>The same original values appear in {cap.windows?'Windows Settings':'System Settings / System Preferences'}. This window keeps only its own view mode and pointer tracking.</p>{/if}<p>This is a genuine pixel loupe over the original simulated desktop DOM, not CSS scaling or a host screen capture. Lens, window and docked views draw the captured source pixels with smoothing off; edges are clamped to the original image rectangle.</p><p>{cap.windows?'Windows key + Plus / Minus changes zoom; Windows key + Escape turns zoom off. Ctrl–Alt–L selects Lens, Ctrl–Alt–D Docked, Ctrl–Alt–F Full Screen (shown in this local window).':'Option–Command–8 toggles shared Zoom; Option–Command–Plus / Minus changes magnification.'} Ctrl–Alt–Arrow keys pan by 40 scene pixels. Follow Pointer tracks real desktop client coordinates. Refresh captures a new actual DOM raster.</p><p>{cap.qualification}</p><button data-capture-control="sheet:done" onclick={()=>command('sheet',{sheet:null})}>Done</button></div>{/if}
 {:else}<p role="alert">The original Magnifier scene window is unavailable.</p>{/if}
</section>
